<template>
  <section class="manager"><header><div><h3>Pump &amp; nozzle register</h3><p>Maintain the station's physical pump and nozzle map for manual shift capture or later integration.</p></div><span class="badge">{{ pumps.length }} configured</span></header>
    <form class="form" @submit.prevent="addPump"><label>Pump number<input v-model.trim="form.pump" required placeholder="Pump 1" /></label><label>Nozzle / grade<input v-model.trim="form.grade" required placeholder="Nozzle A · Diesel" /></label><label>Product<select v-model="form.product"><option>Petrol</option><option>Diesel</option><option>Kerosene</option></select></label><label>Meter serial (optional)<input v-model.trim="form.serial" /></label><button class="primary">Add nozzle</button></form>
    <div class="cards"><article v-for="pump in pumps" :key="pump.id"><div class="pump-icon">⛽</div><div class="details"><strong>{{ pump.pump }} · {{ pump.grade }}</strong><span>{{ pump.product }} <template v-if="pump.serial">· Meter {{ pump.serial }}</template></span></div><span class="online"><i></i>Manual</span><button class="remove" aria-label="Remove pump nozzle" @click="$emit('remove', pump.id)">Remove</button></article><div v-if="!pumps.length" class="empty">Add the station's pump nozzles to create a clear register.</div></div>
    <aside><strong>Hardware integration status</strong><p>No pump controller is connected. This register organizes station equipment; live readings require a supported controller, protocol adapter and backend ingestion endpoint.</p></aside>
  </section>
</template>
<script setup>
import { reactive } from 'vue'
defineProps({ pumps: { type: Array, default: () => [] } })
const emit = defineEmits(['add', 'remove'])
const form = reactive({ pump: '', grade: '', product: 'Petrol', serial: '' })
function addPump() { emit('add', { ...form, id: crypto.randomUUID() }); Object.assign(form, { pump: '', grade: '', product: 'Petrol', serial: '' }) }
</script>
<style scoped>
